-- Aquagram — 0081: Bitkiler 1. parti (56 tür)
insert into public.species (slug, name, latin, category_id, kind, difficulty, temperament, description, facts, keywords, care_notice, range_areas, name_note, status, content_updated_at)
select e->>'s', e->>'n', e->>'l', coalesce(e->>'g', 'govdeli'), coalesce(e->>'kd', 'fish'), e->>'d', e->>'t', e->>'x',
 (select jsonb_agg(jsonb_build_array((array['Işık','CO2','Büyüme hızı','Yerleşim','Sıcaklık','pH','Çoğaltma','Boy','Köken','Özellikler'])[i], e->'f'->>(i-1)) order by i) from generate_series(1,10) i),
 array(select jsonb_array_elements_text(e->'k')), e->>'c',
 coalesce((select jsonb_agg(jsonb_build_object('lat', g->0, 'lng', g->1, 'r', g->2, 'label', g->>3)) from jsonb_array_elements(e->'a') g), '[]'::jsonb),
 e->>'m', 'published', now()
from jsonb_array_elements('[{"s":"hygrophila-polysperma","n":"Hygrophila polysperma","l":"Hygrophila polysperma","d":"Kolay","t":null,"x":"Açık yeşil, mızrak biçimli yapraklı, çok hızlı büyüyen ve neredeyse her koşula uyum sağlayan bir gövdeli bitki. Güçlü ışıkta tepe yaprakları pembeleşir.","f":["Düşük–Orta","Gerekmez","Hızlı","Orta / arka plan","20–28 °C","6.0–8.0","Tepe çeliği","20–40 cm","Hindistan ve Güneydoğu Asya","Dayanıklı başlangıç bitkisi"],"k":["hygrophila polysperma","dwarf hygrophila","higrofila"],"c":"Bazı ülkelerde doğaya karıştığı için istilacı sayılır; budama artıklarını kanalizasyona ya da doğaya atma.","a":[],"m":null,"g":"govdeli","kd":"plant"},{"s":"hygrophila-corymbosa","n":"Hygrophila corymbosa","l":"Hygrophila corymbosa","d":"Kolay","t":null,"x":"Geniş yapraklı, iri ve gür büyüyen bir Hygrophila. ''Siamensis'', ''Stricta'' ve ''Kompakt'' gibi çok sayıda ticari formu vardır.","f":["Orta","Faydalı","Hızlı","Arka plan","22–28 °C","6.0–7.5","Tepe çeliği","30–60 cm","Güneydoğu Asya","İri yapraklı, gür"],"k":["hygrophila corymbosa","giant hygrophila","temple plant","siamensis","stricta"],"c":null,"a":[],"m":null,"g":"govdeli","kd":"plant"},{"s":"hygrophila-difformis","n":"Hygrophila difformis","l":"Hygrophila difformis","d":"Kolay","t":null,"x":"Su altında derin dilimli, dantel gibi yapraklar geliştiren açık yeşil bir bitki. Hobide ''water wisteria'' olarak bilinir; yeni başlayanlar için en kolay bitkilerdendir.","f":["Orta","Faydalı","Hızlı","Orta / arka plan","22–28 °C","6.0–7.5","Tepe çeliği, yan sürgün","20–40 cm","Güney ve Güneydoğu Asya","Dantelli yapraklar"],"k":["hygrophila difformis","water wisteria","su güzeli"],"c":null,"a":[],"m":null,"g":"govdeli","kd":"plant"},{"s":"hygrophila-lancea-araguaia","n":"Hygrophila lancea ''Araguaia''","l":"Hygrophila lancea ''Araguaia''","d":"Orta","t":null,"x":"İnce ve uzun yaprakları güçlü ışıkta kırmızı-kahve tonlara bürünen, kompakt bir Hygrophila. Hollanda tipi akvaryumlarda sevilir.","f":["Orta–Yüksek","Önerilir","Orta","Orta plan","22–28 °C","5.5–7.0","Tepe çeliği","10–25 cm","Kültivar (Brezilya kökenli)","İnce, kırmızı yapraklar"],"k":["hygrophila araguaia","hygrophila lancea","araguaia"],"c":null,"a":[],"m":null,"g":"govdeli","kd":"plant"},{"s":"limnophila-aromatica","n":"Limnophila aromatica","l":"Limnophila aromatica","d":"Orta","t":null,"x":"Güçlü ışıkta mor-pembe tonlara bürünen, ezildiğinde limon kokusu yayan bir gövdeli bitki. Asya mutfağında da kullanılır.","f":["Orta–Yüksek","Önerilir","Hızlı","Arka plan","22–28 °C","5.5–7.5","Tepe çeliği","30–50 cm","Güneydoğu Asya","Kokulu, mor-pembe yapraklar"],"k":["limnophila aromatica","rice paddy herb","ambulia"],"c":null,"a":[],"m":null,"g":"govdeli","kd":"plant"},{"s":"ludwigia-glandulosa","n":"Ludwigia glandulosa","l":"Ludwigia glandulosa","d":"Orta","t":null,"x":"Uzun, mızrak biçimli yaprakları güçlü ışık ve demir gübresiyle koyu kırmızı-mora dönen gösterişli bir Ludwigia.","f":["Yüksek","Önerilir","Orta","Orta / arka plan","22–28 °C","5.5–7.0","Tepe çeliği","20–40 cm","Kuzey Amerika","Koyu kırmızı-mor yapraklar"],"k":["ludwigia glandulosa","ludwigia perennis","ludwigia peruensis"],"c":null,"a":[],"m":"Ticarette ''L. perennis'' ya da ''L. peruensis'' adlarıyla da satılır.","g":"govdeli","kd":"plant"},{"s":"ludwigia-ovalis","n":"Ludwigia ovalis","l":"Ludwigia ovalis","d":"Orta","t":null,"x":"Küçük yuvarlak yaprakları turuncu-pembe tonlara bürünen, yayvan büyüyen zarif bir Ludwigia.","f":["Orta–Yüksek","Önerilir","Orta","Orta plan","20–28 °C","5.5–7.0","Tepe çeliği","15–30 cm","Doğu Asya","Yuvarlak, pembe-turuncu yapraklar"],"k":["ludwigia ovalis","ovalis"],"c":null,"a":[],"m":null,"g":"govdeli","kd":"plant"},{"s":"myriophyllum-tuberculatum","n":"Myriophyllum tuberculatum","l":"Myriophyllum tuberculatum","d":"Zor","t":null,"x":"İnce bölünmüş yaprakları güçlü ışıkta parlak kırmızıya dönen, ''red foxtail'' olarak bilinen bir bitki.","f":["Yüksek","Gerekli","Hızlı","Arka plan","22–28 °C","5.5–7.0","Tepe çeliği","30–60 cm","Güney Asya","Kırmızı tüylü yapraklar"],"k":["myriophyllum tuberculatum","red foxtail","kırmızı tilki kuyruğu"],"c":"Yüksek ışık, CO2 ve düzenli gübre ister; yeni başlayanlar için uygun değildir.","a":[],"m":null,"g":"govdeli","kd":"plant"},{"s":"egeria-densa","n":"Egeria densa","l":"Egeria densa","d":"Kolay","t":null,"x":"Kalın gövdeli, sık yapraklı ve çok hızlı büyüyen klasik bir ''su veba otu''. Besin fazlasını hızla çekerek yosunla rekabet eder.","f":["Düşük–Orta","Gerekmez","Çok hızlı","Arka plan","10–26 °C","6.5–8.0","Gövde parçası","50–100 cm","Güney Amerika","Soğuk suya dayanıklı"],"k":["egeria densa","elodea densa","brazilian waterweed","su vebası","anacharis"],"c":"Doğaya karıştığında istilacı olur; budama artıklarını doğaya atma.","a":[],"m":"Eski kaynaklarda Elodea densa adıyla geçer.","g":"govdeli","kd":"plant"},{"s":"elodea-canadensis","n":"Elodea canadensis","l":"Elodea canadensis","d":"Kolay","t":null,"x":"Küçük yapraklı, serin suyu seven bir su veba otu; havuzlar ve ısıtıcısız akvaryumlar için uygundur.","f":["Düşük–Orta","Gerekmez","Hızlı","Arka plan","10–24 °C","6.5–8.0","Gövde parçası","30–60 cm","Kuzey Amerika","Soğuk su ve havuz bitkisi"],"k":["elodea canadensis","canadian waterweed","su vebası"],"c":"Avrupa''da istilacı türdür; doğaya bırakma.","a":[],"m":null,"g":"govdeli","kd":"plant"},{"s":"cabomba-caroliniana","n":"Cabomba caroliniana","l":"Cabomba caroliniana","d":"Orta","t":null,"x":"Yelpaze gibi ince bölünmüş açık yeşil yapraklarıyla yumuşak bir arka plan oluşturan klasik bir bitki.","f":["Orta–Yüksek","Faydalı","Hızlı","Arka plan","20–27 °C","6.0–7.5","Tepe çeliği","30–60 cm","Amerika kıtası","Yelpaze biçimli yapraklar"],"k":["cabomba caroliniana","cabomba","green cabomba"],"c":"Işık yetersiz kalırsa alt yaprakları dökülür.","a":[],"m":null,"g":"govdeli","kd":"plant"},{"s":"cabomba-furcata","n":"Cabomba furcata","l":"Cabomba furcata","d":"Zor","t":null,"x":"Cabomba''nın kırmızı-mor tonlu, zor yetişen ama çok gösterişli türü.","f":["Yüksek","Gerekli","Orta","Arka plan","22–28 °C","5.5–7.0","Tepe çeliği","30–60 cm","Orta ve Güney Amerika","Kırmızı-mor yelpaze yapraklar"],"k":["cabomba furcata","red cabomba","kırmızı cabomba","cabomba piauhyensis"],"c":"Yüksek ışık, CO2 ve yumuşak su ister.","a":[],"m":null,"g":"govdeli","kd":"plant"},{"s":"pogostemon-yatabeanus","n":"Pogostemon yatabeanus","l":"Pogostemon yatabeanus","d":"Orta","t":null,"x":"İnce, iğne gibi yaprakları halka hâlinde dizilen zarif bir gövdeli bitki.","f":["Orta–Yüksek","Önerilir","Orta","Orta plan","20–28 °C","5.5–7.0","Tepe çeliği","15–30 cm","Doğu Asya","İnce iğne yapraklar"],"k":["pogostemon yatabeanus","eusteralis yatabeana"],"c":null,"a":[],"m":null,"g":"govdeli","kd":"plant"},{"s":"pogostemon-deccanensis","n":"Pogostemon deccanensis","l":"Pogostemon deccanensis","d":"Orta","t":null,"x":"İnce yapraklı, açık yeşil ve yumuşak dokulu bir Pogostemon. Arka planda doku farkı yaratmak için kullanılır.","f":["Orta–Yüksek","Önerilir","Orta","Orta / arka plan","22–28 °C","5.5–7.0","Tepe çeliği","20–40 cm","Hindistan","Açık yeşil iğne yapraklar"],"k":["pogostemon deccanensis","pogostemon ''deccanensis''"],"c":null,"a":[],"m":null,"g":"govdeli","kd":"plant"},{"s":"lindernia-rotundifolia","n":"Lindernia rotundifolia","l":"Lindernia rotundifolia","d":"Kolay","t":null,"x":"Küçük yuvarlak yapraklı, yayvan büyüyen kolay bir bitki. ''Variegata'' formunda yapraklar beyaz desenlidir.","f":["Düşük–Orta","Faydalı","Orta","Ön / orta plan","20–28 °C","6.0–7.5","Tepe çeliği","5–15 cm","Hindistan ve Sri Lanka","Küçük yuvarlak yapraklar"],"k":["lindernia rotundifolia","lindernia","variegata"],"c":null,"a":[],"m":null,"g":"govdeli","kd":"plant"},{"s":"bacopa-monnieri","n":"Bacopa monnieri","l":"Bacopa monnieri","d":"Kolay","t":null,"x":"Kalın, etli ve küçük yapraklı dayanıklı bir Bacopa. Geniş sıcaklık ve su sertliği aralığına uyum sağlar.","f":["Orta","Gerekmez","Orta","Orta / arka plan","18–28 °C","6.0–8.0","Tepe çeliği","20–40 cm","Tropikal ve subtropikal bölgeler","Etli küçük yapraklar"],"k":["bacopa monnieri","moneywort","bacopa"],"c":null,"a":[],"m":null,"g":"govdeli","kd":"plant"},{"s":"gymnocoronis-spilanthoides","n":"Gymnocoronis spilanthoides","l":"Gymnocoronis spilanthoides","d":"Kolay","t":null,"x":"İri yapraklı ve çok hızlı büyüyen, yüzeye ulaşınca suyun dışına çıkıp çiçek açabilen bir bitki.","f":["Orta–Yüksek","Gerekmez","Çok hızlı","Arka plan","20–28 °C","6.0–8.0","Tepe çeliği","50+ cm","Güney Amerika","Çok hızlı, iri"],"k":["gymnocoronis spilanthoides","senegal tea plant"],"c":"Bazı ülkelerde istilacı olarak yasaklıdır; doğaya karıştırma.","a":[],"m":null,"g":"govdeli","kd":"plant"},{"s":"didiplis-diandra","n":"Didiplis diandra","l":"Didiplis diandra","d":"Zor","t":null,"x":"İnce iğne biçimli yaprakları güçlü ışıkta kırmızımsı tonlar alan narin bir bitki.","f":["Yüksek","Gerekli","Orta","Orta plan","20–28 °C","5.5–7.0","Tepe çeliği","10–25 cm","Kuzey Amerika","İnce, kırmızımsı uçlar"],"k":["didiplis diandra","water hedge"],"c":"Besin eksikliğine duyarlıdır; düzenli gübre ister.","a":[],"m":null,"g":"govdeli","kd":"plant"},{"s":"mayaca-fluviatilis","n":"Mayaca fluviatilis","l":"Mayaca fluviatilis","d":"Orta","t":null,"x":"İnce yaprakları yosuna benzeyen, açık yeşil ve yumuşak görünümlü bir bitki.","f":["Orta–Yüksek","Önerilir","Hızlı","Orta / arka plan","22–28 °C","5.0–7.0","Tepe çeliği","20–40 cm","Amerika kıtası","Yumuşak, tüy gibi doku"],"k":["mayaca fluviatilis","mayaca"],"c":"Yumuşak, asidik su ister; sert suda sararır.","a":[],"m":null,"g":"govdeli","kd":"plant"},{"s":"hydrocotyle-leucocephala","n":"Hydrocotyle leucocephala","l":"Hydrocotyle leucocephala","d":"Kolay","t":null,"x":"Yuvarlak parlak yaprakları zincir gibi dizilen, yüzeye ulaşınca yüzerek de büyüyebilen kolay bir bitki.","f":["Orta","Gerekmez","Hızlı","Orta / arka plan, yüzey","20–28 °C","6.0–8.0","Gövde parçası","20–50 cm","Güney Amerika","Yuvarlak, parlak yapraklar"],"k":["hydrocotyle leucocephala","brazilian pennywort","su parası"],"c":null,"a":[],"m":null,"g":"govdeli","kd":"plant"},{"s":"micranthemum-glomeratum","n":"Micranthemum glomeratum","l":"Micranthemum glomeratum","d":"Kolay","t":null,"x":"Hobide ''pearl weed'' olarak bilinen, küçük yapraklı ve gür büyüyen bir bitki. Güçlü ışıkta yapraklarında oksijen kabarcıkları birikir.","f":["Orta","Faydalı","Hızlı","Orta plan","20–28 °C","6.0–7.5","Tepe çeliği","10–30 cm","Kuzey Amerika (Florida)","Küçük yapraklı, gür"],"k":["micranthemum glomeratum","hemianthus micranthemoides","pearl weed","pearlweed"],"c":null,"a":[],"m":"Ticarette ''Hemianthus micranthemoides'' adıyla satılan bitkilerin çoğu aslında bu türdür.","g":"govdeli","kd":"plant"},{"s":"ammannia-gracilis","n":"Ammannia gracilis","l":"Ammannia gracilis","d":"Orta","t":null,"x":"Uzun, ince yaprakları turuncu-kırmızı tonlarda olan, arka plana renk katan bir Ammannia.","f":["Yüksek","Önerilir","Orta","Arka plan","22–28 °C","5.5–7.0","Tepe çeliği","30–50 cm","Batı Afrika","Turuncu-kırmızı uzun yapraklar"],"k":["ammannia gracilis","ammannia"],"c":null,"a":[],"m":null,"g":"govdeli","kd":"plant"},{"s":"ammannia-pedicellata-golden","n":"Ammannia pedicellata ''Golden''","l":"Ammannia pedicellata ''Golden''","d":"Zor","t":null,"x":"Yaprakları altın sarısı ve turuncu tonlarda olan, renkli düzenlerde vurgu bitkisi olarak kullanılan bir Ammannia.","f":["Yüksek","Gerekli","Orta","Orta / arka plan","22–28 °C","5.5–7.0","Tepe çeliği","20–40 cm","Kültivar (Doğu Afrika kökenli)","Altın sarısı-turuncu yapraklar"],"k":["ammannia pedicellata golden","nesaea golden","ammannia golden"],"c":"Yüksek ışık, CO2 ve yeterli besin ister.","a":[],"m":"Eski adıyla Nesaea pedicellata ''Golden'' olarak da satılır.","g":"govdeli","kd":"plant"},{"s":"limnophila-heterophylla","n":"Limnophila heterophylla","l":"Limnophila heterophylla","d":"Kolay","t":null,"x":"Halka hâlinde dizilen, ince bölünmüş yapraklarıyla Limnophila sessiliflora''ya benzeyen hızlı büyüyen bir bitki.","f":["Orta","Faydalı","Hızlı","Arka plan","22–28 °C","6.0–7.5","Tepe çeliği","30–50 cm","Güney ve Doğu Asya","İnce bölünmüş yapraklar"],"k":["limnophila heterophylla","limnophila"],"c":null,"a":[],"m":null,"g":"govdeli","kd":"plant"},{"s":"hottonia-palustris","n":"Hottonia palustris","l":"Hottonia palustris","d":"Orta","t":null,"x":"Avrupa''nın yerli su bitkisi; ince bölünmüş yapraklarıyla serin sulu ve ısıtıcısız akvaryumlara uygundur.","f":["Orta","Faydalı","Orta","Arka plan","10–22 °C","6.0–7.5","Tepe çeliği","20–40 cm","Avrupa ve Batı Asya","Serin su bitkisi"],"k":["hottonia palustris","water violet","su menekşesi"],"c":"Yüksek sıcaklıkta zayıflar.","a":[],"m":null,"g":"govdeli","kd":"plant"},{"s":"rotala-indica","n":"Rotala indica","l":"Rotala indica","d":"Kolay","t":null,"x":"Küçük oval yapraklı, güçlü ışıkta uçları pembeleşen kolay bir Rotala.","f":["Orta","Faydalı","Hızlı","Orta / arka plan","20–28 °C","6.0–7.5","Tepe çeliği","20–40 cm","Güney ve Doğu Asya","Pembe uçlar"],"k":["rotala indica","rotala"],"c":null,"a":[],"m":"Ticarette ''Rotala indica'' adıyla satılan bitkilerin bir kısmı aslında R. rotundifolia''dır.","g":"govdeli","kd":"plant"},{"s":"rotala-ramosior","n":"Rotala ramosior","l":"Rotala ramosior","d":"Orta","t":null,"x":"Kompakt büyüyen, ışık arttıkça pembe-turuncu tonlar alan bir Rotala. ''Florida'' formu hobide yaygındır.","f":["Orta–Yüksek","Önerilir","Orta","Orta plan","20–28 °C","5.5–7.0","Tepe çeliği","10–30 cm","Kuzey Amerika","Pembe-turuncu kompakt"],"k":["rotala ramosior","rotala florida","toothcup"],"c":null,"a":[],"m":null,"g":"govdeli","kd":"plant"},{"s":"vallisneria-spiralis","n":"Vallisneria spiralis","l":"Vallisneria spiralis","d":"Kolay","t":null,"x":"Uzun, şerit biçimli yaprakları akıntıda dalgalanan klasik bir arka plan bitkisi. Yan sürgünlerle hızla çoğalır.","f":["Düşük–Orta","Gerekmez","Hızlı","Arka plan","18–28 °C","6.5–8.0","Yan sürgün (stolon)","30–60 cm","Avrupa, Asya ve Afrika","Şerit yapraklar"],"k":["vallisneria spiralis","vallisneria","valis","su şeridi"],"c":null,"a":[],"m":null,"g":"rozet","kd":"plant"},{"s":"vallisneria-americana","n":"Vallisneria americana","l":"Vallisneria americana","d":"Kolay","t":null,"x":"Uzun ve geniş yapraklarıyla büyük tankların arka planını dolduran iri bir Vallisneria. ''Gigantea'' formu hobide yaygındır.","f":["Orta","Gerekmez","Hızlı","Arka plan","18–28 °C","6.5–8.0","Yan sürgün (stolon)","50–150 cm","Kuzey Amerika ve Avustralya","Çok uzun, geniş yapraklar"],"k":["vallisneria americana","vallisneria gigantea","jungle val","dev vallisneria"],"c":"Uzun yapraklar yüzeyde yayılıp ışığı kesebilir; düzenli budanmalı.","a":[],"m":null,"g":"rozet","kd":"plant"},{"s":"vallisneria-nana","n":"Vallisneria nana","l":"Vallisneria nana","d":"Kolay","t":null,"x":"İnce ve görece kısa yapraklı, orta boy tanklar için uygun bir Vallisneria.","f":["Orta","Faydalı","Orta","Orta / arka plan","20–28 °C","6.5–8.0","Yan sürgün (stolon)","20–40 cm","Avustralya","İnce, kısa yapraklar"],"k":["vallisneria nana","dwarf vallisneria"],"c":null,"a":[],"m":null,"g":"rozet","kd":"plant"}]'::jsonb) x(e) on conflict (slug) do nothing;
